      review.append(el('summary', `Reviewed output schema · ${queries.length} queries · ${queries.reduce((count, [, columns]) => count + columns.length, 0)} columns`),
        el('p', 'This ordered native review is retained in the source definition and checked by the original ClickHouse release engine at every start.', 'hint'));
      for (const [query, columns] of queries) {
        review.append(el('h4', query));
        const wrap = el('div', undefined, 'fleet-table-wrap'), table = el('table'), head = el('thead'), row = el('tr');
        for (const label of ['Order', 'Column', 'ClickHouse type']) { const th = el('th', label); th.scope = 'col'; row.append(th); }
        head.append(row); table.append(head); const body = el('tbody');
        for (const [index, column] of columns.entries()) {
          const item = el('tr'); item.append(el('td', index + 1), el('td', column.name), el('td', column.type)); body.append(item);
        }
        table.append(body); wrap.append(table); review.append(wrap);
      }
      card.append(review);
    } else card.append(el('p', 'Import the original workspace’s source JSON to retain its prior ordered output-schema review with this package.', 'hint'));
  }
  const runtime = el('div', undefined, 'fleet-runtime-options');
  runtime.append(check('Allow a local facilitator on this host', source.allowLocalFacilitator, key + '.allowLocalFacilitator',
    value => { source.allowLocalFacilitator = value; }));
  if (['workspace', 'jsonrpcPackage'].includes(source.kind)) runtime.append(check('Allow declared loopback upstreams', source.allowLoopbackUpstream,
    key + '.allowLoopbackUpstream', value => { source.allowLoopbackUpstream = value; }));
